 return { messages, draft, enabled, get speech() { return speech } }
}
async function blocked(f: ReturnType<typeof mount>) {
 await settle()
 // A live reply reaches blocked audio by streaming in after entry (R3); a
 // settled row is read through the manual replay entry.
 if (f.messages.value.length) f.speech.replay(f.messages.value[0]!)
 else f.messages.value.push(message('m', true, '正文 m。生成中'))
 await settle()
